-- =====================================================================
-- Task Mgnt restore, step 2 of 2: DATA (run AFTER 1-schema.sql) — from the DATA backup of Supabase project tazlvzjalhxsudceabqy
-- Taken 8 Oct 2026 (app version 2.3, last migration 20261005100000_whatsapp_pause).
--
-- Restore into a NEW Supabase project:
--   1. Run schema.sql (all migrations in order) in the SQL editor — creates tables, functions, triggers, cron jobs.
--   2. Run this file. Triggers and foreign-key checks are switched off while it loads, so nothing
--      (notifications, WhatsApp, push) fires for the old rows. Rows that already exist are skipped.
--   3. Users log in with "Forgot password" (password hashes are not in this backup).
--   4. Re-enter secrets: WATI token (Settings → WhatsApp in the app), Edge Function secrets
--      (GEMINI_API_KEY, GOOGLE_SERVICE_ACCOUNT_JSON). push-sender makes new VAPID keys on first run,
--      so everyone turns phone notifications on again (My Profile → Phone Notifications).
--   5. Deploy the 5 Edge Functions from supabase/functions and re-upload attachment files if needed.
-- NOT included: password hashes, Vault secrets, Storage files (only their list, below).
-- =====================================================================
begin;
set local session_replication_role = replica;

-- auth.users (password hashes NOT included: users set a new password with "Forgot password")
insert into auth.users (instance_id, id, aud, role, email, phone, email_confirmed_at, raw_app_meta_data, raw_user_meta_data, created_at, updated_at) select instance_id, id, aud, role, email, phone, email_confirmed_at, raw_app_meta_data, raw_user_meta_data, created_at, updated_at from json_populate_recordset(null::auth.users, convert_from(decode('', 'base64'), 'UTF8')::json) on conflict do nothing;
insert into auth.identities (id, user_id, provider_id, provider, identity_data, created_at, updated_at) select id, user_id, provider_id, provider, identity_data, created_at, updated_at from json_populate_recordset(null::auth.identities, convert_from(decode('', 'base64'), 'UTF8')::json) on conflict do nothing;

-- Supabase Auth can't read NULL in these text columns ("Database error querying schema"): make them blank.
update auth.users set
  encrypted_password = coalesce(encrypted_password, ''), confirmation_token = coalesce(confirmation_token, ''),
  recovery_token = coalesce(recovery_token, ''), email_change = coalesce(email_change, ''),
  email_change_token_new = coalesce(email_change_token_new, ''), email_change_token_current = coalesce(email_change_token_current, ''),
  phone_change = coalesce(phone_change, ''), phone_change_token = coalesce(phone_change_token, ''),
  reauthentication_token = coalesce(reauthentication_token, '');

-- ===================== public tables =====================
-- The schema step seeds roles / reminder_rules / perisclaw_settings / health_check with fresh ids; they are replaced by the original rows.
-- Start clean (also makes it safe to run this file again after a failed attempt).
delete from public.health_check;
delete from public.notifications;
delete from public.perisclaw_entries;
delete from public.perisclaw_settings;
delete from public.profiles;
delete from public.recurring_tasks;
delete from public.reel_views;
delete from public.reminder_rules;
delete from public.roles;
delete from public.task_activity;
delete from public.task_attachments;
delete from public.task_attendees;
delete from public.task_comments;
delete from public.task_meetings;
delete from public.task_reels;
delete from public.task_reminders;
delete from public.task_time_entries;
delete from public.tasks;
delete from public.teams;
delete from public.whatsapp_outbox;
delete from public.push_outbox;
delete from public.push_subscriptions;

insert into public.health_check overriding system value select * from json_populate_recordset(null::public.health_check, convert_from(decode('W3siaWQiOjEsIm1lc3NhZ2UiOiJTdXBhYmFzZSBkYXRhYmFzZSBpcyByZWFjaGFibGUiLCJjcmVhdGVkX2F0IjoiMjAyNi0wOS0yNVQwODoyNTowMy40MjUzMTgrMDA6MDAifV0=', 'base64'), 'UTF8')::json) on conflict do nothing;
